for(const field of ['input','sourceDraft','priorSourceDraft','priorDsl','priorReport','executionOptions'])it(`restoration rejects a self-consistent foreign retained ${field} binding`,async()=>withNetworkGuard(async()=>{const f=await graphRestorationScenario();try{
 const claim=await f.store.get('repair_application',f.parent.id),phase=claim.authorizationCloseout,dir=phase.artifactsDir,plan=JSON.parse(fs.readFileSync(path.join(dir,'plan.json'))),receipt=JSON.parse(fs.readFileSync(path.join(dir,'receipt.json')));
 plan.bindings[field]={foreign:'artifact'};plan.evidenceDigest=sha256Digest(plan.bindings);phase.result.evidenceDigest=plan.evidenceDigest;receipt.intent.evidenceDigest=plan.evidenceDigest;phase.journal=phase.journal.map(e=>({...e,intent:clone(receipt.intent)}));
 fs.writeFileSync(path.join(dir,'plan.json'),JSON.stringify(plan));fs.writeFileSync(path.join(dir,'receipt.json'),JSON.stringify(receipt));f.grant.resultDigest=sha256Digest(phase.result);await f.store.mutate('repair_application',claim.id,()=>claim);await f.store.mutate('item',f.item.id,v=>({...v,attempts:v.attempts.map((a,i)=>i===v.attempts.length-1?{...a,report:clone(phase.result)}:a)}));
 const count=writes(f.c).length,p=await previewScopedRepair(f.store,f.restoreRepair.id,f.restoreOptions);assert.equal(p.summary.applicable,0);assert.equal(p.items[0].preview?.diagnostics[0].code,'authorization_closeout.restore_plan_mismatch');assert.equal(writes(f.c).length,count);
 }finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
for(const field of ['templateWriteOutcomeUnknown','transferRecordOutcomeUnknown'])it(`restoration rejects a contradictory ${field} on its acknowledged parent receipt`,async()=>withNetworkGuard(async()=>{const f=await graphRestorationScenario();try{await f.store.mutate('repair_application',f.parent.id,v=>({...v,authorizationCloseout:{...v.authorizationCloseout,result:{...v.authorizationCloseout.result,[field]:true}}}));const p=await previewScopedRepair(f.store,f.restoreRepair.id,f.restoreOptions);assert.equal(p.summary.applicable,0);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
it('executor accepts a matching completed canonical historical lock without changing it',async()=>withNetworkGuard(async()=>{const f=await scenario('repair_readers');try{const file=path.join(f.options.testHistoricalLockRoot,sha256Digest({baseUrl:ORIGIN,targetTemplateId:TARGET}).slice(7)+'.json'),bytes=JSON.stringify({baseUrl:ORIGIN,targetTemplateId:TARGET,templateWriteCompleted:true,templateWriteOutcomeUnknown:false,transferRecordCompleted:true,transferRecordOutcomeUnknown:false});fs.writeFileSync(file,bytes);const p=await closeoutDraftAuthorization(f.dsl,f.options);assert.equal(p.ok,true,JSON.stringify(p.diagnostics));assert.equal(fs.readFileSync(file,'utf8'),bytes);assert.deepEqual(writes(f.c),[]);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
it('record finalization cannot replace the canonical permanent lock with a matching private copy',async()=>withNetworkGuard(async()=>{const f=await scenario('finalize_record');try{const copyFile=path.join(f.root,'private-copy.json');fs.copyFileSync(f.parentLock,copyFile);f.options.retainedPermanentLockPath=copyFile;const p=await closeoutDraftAuthorization(f.dsl,f.options);assert.equal(p.ok,false);assert.ok(p.diagnostics.some(d=>d.code==='authorization_closeout.canonical_historical_lock_mismatch'));assert.deepEqual(writes(f.c),[]);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));

it('an unknown status in a canonical completed-looking lock still blocks reader repair',async()=>withNetworkGuard(async()=>{const f=await scenario('repair_readers');try{fs.writeFileSync(path.join(f.options.testHistoricalLockRoot,sha256Digest({baseUrl:ORIGIN,targetTemplateId:TARGET}).slice(7)+'.json'),JSON.stringify({baseUrl:ORIGIN,targetTemplateId:TARGET,status:'outcome_unknown',templateWriteCompleted:true,templateWriteOutcomeUnknown:false,transferRecordCompleted:true,transferRecordOutcomeUnknown:false}));const p=await closeoutDraftAuthorization(f.dsl,f.options);assert.equal(p.ok,false);assert.deepEqual(writes(f.c),[]);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
it('a dangling canonical historical lock is not absence evidence',async()=>withNetworkGuard(async()=>{const f=await scenario('repair_readers');try{fs.symlinkSync(path.join(f.root,'missing-private-state'),path.join(f.options.testHistoricalLockRoot,sha256Digest({baseUrl:ORIGIN,targetTemplateId:TARGET}).slice(7)+'.json'));const p=await closeoutDraftAuthorization(f.dsl,f.options);assert.equal(p.ok,false);assert.deepEqual(writes(f.c),[]);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));

it('malformed uncertainty flags never become evidence of a known write',async()=>withNetworkGuard(async()=>{for(const value of ['false',0,null]){const f=await scenario('repair_readers');try{f.options.priorExecutionReport.templateWriteOutcomeUnknown=value;f.options.expectedPriorReportDigest=sha256Digest(f.options.priorExecutionReport);const p=await closeoutDraftAuthorization(f.dsl,f.options);assert.equal(p.ok,false);assert.deepEqual(writes(f.c),[]);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}}));
for(const value of [false,0])it(`exact restoration rejects a malformed graph value ${value}`,async()=>withNetworkGuard(async()=>{const f=await graphRestorationScenario();try{const file=path.join(f.parent.authorizationCloseout.artifactsDir,'after.json'),after=JSON.parse(fs.readFileSync(file));after.workflow.fdContent=value;after.template.mechanisms.lbpmTemplate[0].fdContent=value;f.c.workflowDraft.fdContent=value;f.c.template.mechanisms.lbpmTemplate[0].fdContent=value;fs.writeFileSync(file,JSON.stringify(after));f.grant.snapshotDigest=sha256Digest(after);const count=writes(f.c).length,p=await previewScopedRepair(f.store,f.restoreRepair.id,f.restoreOptions);assert.equal(p.summary.applicable,0);assert.equal(writes(f.c).length,count);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));

it('closeout rejects a still-running executor in an already paused origin',async()=>withNetworkGuard(async()=>{const f=await batchScenario('repair_readers');try{await f.store.create('item','in-flight-item',{batchId:f.batch.id,baseUrl:ORIGIN,status:'running',workerId:'retained-worker',leaseUntil:new Date(Date.now()+60000).toISOString()});const p=await previewScopedRepair(f.store,f.repair.id,f.batchOptions);assert.equal(p.summary.applicable,1);await assert.rejects(()=>applyScopedRepair(f.store,p.id,{...f.batchOptions,confirmWrite:true,expectedDigest:p.digest,actor:'operator',artifactsRoot:path.join(f.root,'apply')}),e=>e.code==='batch.authorization_closeout.origin_worker_running');assert.deepEqual(writes(f.c),[]);assert.equal((await f.store.list('repair_application')).length,0);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
it('closeout rejects a retained applying repair before creating a target phase',async()=>withNetworkGuard(async()=>{const f=await batchScenario('repair_readers');try{await f.store.create('repair_run','other-apply',{batchId:f.batch.id,status:'applying'});const p=await previewScopedRepair(f.store,f.repair.id,f.batchOptions);assert.equal(p.summary.applicable,1);await assert.rejects(()=>applyScopedRepair(f.store,p.id,{...f.batchOptions,confirmWrite:true,expectedDigest:p.digest,actor:'operator',artifactsRoot:path.join(f.root,'apply')}),e=>e.code==='batch.authorization_closeout.origin_repair_applying');assert.deepEqual(writes(f.c),[]);assert.equal((await f.store.list('repair_application')).length,0);}finally{fs.rmSync(f.root,{recursive:true,force:true});}}));
it('ordinary resume, claims, limit changes and older repairs respect the active closeout until its receipt is finalized',async()=>withNetworkGuard(async()=>{const f=await batchScenario('repair_readers');let release;try{
 await f.store.create('batch','other-origin-batch',{...f.batch,status:'paused'});const oldRepair=await createScopedRepair(f.store,{...f.repair.definition,action:{kind:'locked_draft',repairKind:'template_authorization'}}),oldPreview=await previewScopedRepair(f.store,oldRepair.id,{batchId:f.batch.id,itemIds:[f.item.id],credentials:f.options.credentials});
 const p=await previewScopedRepair(f.store,f.repair.id,f.batchOptions);assert.equal(p.summary.applicable,1);let entered;const barrier=new Promise(r=>{entered=r;}),pending=new Promise(r=>{release=r;}),update=f.c.updateTemplate.bind(f.c);f.c.updateTemplate=async payload=>{entered();await pending;return update(payload);};
 const applying=applyScopedRepair(f.store,p.id,{...f.batchOptions,confirmWrite:true,expectedDigest:p.digest,actor:'operator',artifactsRoot:path.join(f.root,'apply')});await barrier;
 try{
  await assert.rejects(()=>setBatchStatus(f.store,'other-origin-batch','running'),e=>e.code==='BATCH_REPAIR_IN_PROGRESS');
  await assert.rejects(()=>setTargetLimit(f.store,f.batch.id,2,'operator'),e=>e.code==='BATCH_REPAIR_IN_PROGRESS');
  await f.store.mutate('batch','other-origin-batch',v=>({...v,status:'running'}));
  await assert.rejects(()=>claimItem(f.store,'other-origin-batch','execute',{workerId:'cached-worker',leaseMs:60000,engineDigest:engineDigest()}),e=>e.code==='BATCH_REPAIR_IN_PROGRESS');
  await f.store.mutate('batch','other-origin-batch',v=>({...v,status:'paused'}));
  await assert.rejects(()=>applyScopedRepair(f.store,oldPreview.id,{...f.batchOptions,confirmWrite:true,expectedDigest:oldPreview.digest,actor:'operator',artifactsRoot:path.join(f.root,'other-repair')}),e=>e.code==='batch.scoped_repair.origin_closeout_active');
 }finally{release();await applying;}
 assert.equal((await f.store.get('item',f.item.id)).status,'succeeded');await setBatchStatus(f.store,'other-origin-batch','running');assert.equal((await f.store.get('batch','other-origin-batch')).status,'running');assert.equal(writes(f.c).length,1);
 }finally{release?.();fs.rmSync(f.root,{recursive:true,force:true});}}));
